// Authored contexts for the independent tank stations.
for (const [seat, role] of [
  ['cannon', 'tireur principal du tank'],
  ['top', 'mitrailleur supérieur du tank'],
  ['tank-pilot', 'pilote du tank'],
])
  for (const context of ['boarding', 'change', 'exchange-request', 'exchange-accept']) {
    const original = CONTRACTS[context + ':dorsal'];
    if (original)
      CONTRACTS[context + ':' + seat] = original.map((variants, index) =>
        variants.map((doc, n) => ({
          ...doc,
          title: doc.title.replace(/mitrailleur dorsal/gi, role),
          code: 'TANK-' + seat + '-' + context + '-' + index + '-' + n,
          text:
            doc.text.replace(/mitrailleur dorsal/gi, role) +
            '\n\nLe char ne reconnaît pas les priorités à droite. Le signataire reconnaît en revanche la réserve limitée de chaque arme et le droit des deux autres postes à fonctionner sans son autorisation.',
        })),
      );
  }
for (const [type, seat, role] of [
  ['helicopter', 'pilot', 'pilote d’hélicoptère'],
  ['helicopter', 'copilot', 'copilote armement'],
  ['flaktruck', 'pilot', 'conducteur de DCA mobile'],
  ['flaktruck', 'cannon', 'tireur de DCA mobile'],
])
  for (const context of ['boarding', 'change', 'exchange-request', 'exchange-accept'])
    CONTRACTS[context + ':' + type + '-' + seat] = CONTRACTS[context + ':dorsal'].map(
      (variants, index) =>
        variants.map((doc, n) => ({
          ...doc,
          title: doc.title.replace(/mitrailleur dorsal/gi, role),
          code: type + '-' + seat + '-' + context + '-' + index + '-' + n,
          text:
            doc.text.replace(/mitrailleur dorsal/gi, role) +
            '\n\nLe bureau rappelle que changer de poste exige une signature, et ne transfère aucune arme au voisin. La pénurie de munitions ne constitue pas un cas de force administrative.',
        })),
    );
export function contractKey(context, seat = 'pilot', type = null) {
  if (['helicopter', 'flaktruck'].includes(type)) seat = type + '-' + seat;
  if (type === 'tank' && seat === 'pilot') seat = 'tank-pilot';
  return (
    context +
    ':' +
    (context === 'equipment' ? 'dca' : ['purgatory', 'super'].includes(context) ? 'soul' : seat)
  );
}
export class ContractBook {
  constructor(random = Math.random) {
    this.random = random;
    this.last = new Map();
    this.current = new Map();
  }
  get(key, index, session) {
    const stable = key + ':' + index + ':' + session;
    if (this.current.has(stable)) return this.current.get(stable);
    const choices = CONTRACTS[key]?.[index];
    if (!choices) throw Error('Contrat inconnu: ' + key + ':' + index);
    const previous = this.last.get(key + ':' + index),
      eligible = choices.map((_, i) => i).filter((i) => i !== previous);
    const pick =
      eligible[Math.min(eligible.length - 1, Math.floor(this.random() * eligible.length))];
    this.last.set(key + ':' + index, pick);
    const doc = choices[pick];
    this.current.set(stable, doc);
    return doc;
  }
}
